ad08-4cee-80af-86fae66a470c","building_name":"506创新园","target_table":"building_brochure_data","field_name":"parking_total","proposed_value":630,"source":{"url":"https://www.cs.com.cn/ssgs/gsxw/202511/t20251120_6524222.html","publisher":"中国证券报/北京产权交易所转让项目信息","tier":"industry","field_reference":"280地面+260立体停车库+90地下，共630个"},"note":"更正原700个未核证值；630个含公共服务中心地下90个，与自有车位口径需区分。"},{"ref":"AI100-098","building_id":"b095a837-a895-49a6-9de6-ddcde7615f2c","building_name":"京广中心","target_table":"building_brochure_data","field_name":"floors_below","proposed_value":3,"source":{"url":"https://www.jg-zx.cn/index.html","publisher":"京广中心第三方招商平台","tier":"secondary","field_reference":"floors_below: 3","access_date":"2026-11-13"},"note":null},{"ref":"AI100-099","building_id":"b095a837-a895-49a6-9de6-ddcde7615f2c","building_name":"京广中心","target_table":"building_brochure_data","field_name":"parking_total","proposed_value":335,"source":{"url":"https://www.jg-zx.cn/index.html","publisher":"京广中心第三方招商平台","tier":"secondary","field_reference":"parking_total: 335","access_date":"2026-11-13"},"note":null},{"ref":"AI100-100","building_id":"b095a837-a895-49a6-9de6-ddcde7615f2c","building_name":"京广中心","target_table":"building_brochure_data","field_name":"facade_type","proposed_value":"天蓝色玻璃幕墙","source":{"url":"https://cn.govopendata.com/renminribao/1990/10/21/2/","publisher":"人民日报1990年报纸转录","tier":"press","field_reference":"facade_type: 天蓝色玻璃幕墙","access_date":"2026-11-13"},"note":null}]'::jsonb;
  processed integer := 0;
  provenance_status text;
  provenance_tier text;
BEGIN
  PERFORM pg_advisory_xact_lock(801192, 20261113);
  IF jsonb_array_length(input_rows) <> 100 THEN
     RAISE EXCEPTION 'Wrong batch size';
  END IF;
  IF EXISTS(SELECT 1 FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'=batch_ref) THEN
     RAISE EXCEPTION 'Already imported: %',batch_ref;
  END IF;
  FOR v IN SELECT * FROM jsonb_to_recordset(input_rows) AS r(
    ref text, building_id uuid, building_name text, target_table text,
    field_name text, proposed_value jsonb, source jsonb, note text
  )
  LOOP
    IF v.target_table NOT IN ('buildings','building_brochure_data')
       OR NOT EXISTS(SELECT 1 FROM information_schema.columns col
        WHERE col.table_schema='public' AND col.table_name=v.target_table AND col.column_name=v.field_name)
       OR v.proposed_value IS NULL OR v.proposed_value='null'::jsonb
       OR coalesce(v.source->>'url','') NOT LIKE 'https://%' THEN
      RAISE EXCEPTION 'Rejected input for %: %.%',v.ref,v.target_table,v.field_name;
    END IF;
    SELECT b.id,b.name,b.is_active,b.tracking_scope,b.merged_into_id
       INTO project FROM public.buildings b WHERE b.id=v.building_id FOR UPDATE;
    IF NOT FOUND OR project.name IS DISTINCT FROM v.building_name
        OR NOT project.is_active OR project.tracking_scope<>'tracked'
        OR project.merged_into_id IS NOT NULL THEN
      RAISE EXCEPTION 'Building identity mismatch for %',v.ref;
    END IF;
    IF v.target_table='buildings' THEN
      target_id := v.building_id;
    ELSE
      SELECT id INTO target_id FROM public.building_brochure_data
        WHERE building_id=v.building_id FOR UPDATE;
      IF NOT FOUND THEN
        INSERT INTO public.building_brochure_data(building_id)
          VALUES(v.building_id) RETURNING id INTO target_id;
      END IF;
      IF (SELECT count(*) FROM public.building_brochure_data WHERE building_id=v.building_id) <> 1 THEN
        RAISE EXCEPTION 'Brochure record not unique for %',v.ref;
      END IF;
    END IF;
    EXECUTE format('SELECT to_jsonb(t)->%L FROM public.%I t WHERE t.id=$1 FOR UPDATE',
                    v.field_name,v.target_table)
      INTO old_value USING target_id;
    IF old_value IS NOT NULL AND old_value <> 'null'::jsonb AND
       old_value <> '""'::jsonb THEN
      RAISE EXCEPTION 'Field is no longer empty at %: %.%',v.ref,v.target_table,v.field_name;
    END IF;
    IF EXISTS(SELECT 1 FROM public.building_data_field_provenance p
              WHERE p.building_id=v.building_id AND p.target_table=v.target_table
                AND p.field_name=v.field_name AND p.is_current) THEN
      RAISE EXCEPTION 'Current provenance conflicts at %',v.ref;
    END IF;
    changed_id:=NULL;
    EXECUTE format('UPDATE public.%I AS t SET %I=(jsonb_populate_record(NULL::public.%I,jsonb_build_object(%L,$1))).%I WHERE t.id=$2 AND NULLIF(btrim(to_jsonb(t)->>%L),'''') IS NULL RETURNING t.id',
           v.target_table,v.field_name,v.target_table,v.field_name,v.field_name,v.field_name)
      INTO changed_id USING v.proposed_value,target_id;
    IF changed_id IS NULL THEN
      RAISE EXCEPTION 'Concurrent value change for %',v.ref;
    END IF;
    provenance_tier:=CASE v.source->>'tier'
       WHEN 'official' THEN 'primary' WHEN 'legal' THEN 'primary'
       WHEN 'industry' THEN 'authoritative_secondary'
       WHEN 'press' THEN 'authoritative_secondary'
       ELSE 'secondary' END;
    provenance_status:=CASE WHEN v.source->>'tier' IN ('official','legal') THEN 'single_authoritative'
       ELSE 'legacy_backfill' END;
    INSERT INTO public.building_data_field_provenance
      (building_id,brochure_data_id,target_table,field_name,field_value,
       source_type,source_tier,source_name,source_url,source_retrieved_at,
       value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
    VALUES
      (v.building_id,CASE WHEN v.target_table='building_brochure_data' THEN target_id ELSE NULL END,
       v.target_table,v.field_name,v.proposed_value,'internet',provenance_tier,
       v.source->>'publisher',v.source->>'url',now(),now(),provenance_status,
       batch_evidence_id,concat('AI_PUBLIC_RESEARCH; batch=',batch_ref,
         '; candidate=',v.ref,'; sourceTier=',coalesce(v.source->>'tier','unknown'),
         '; original_source_description=',coalesce(v.source->>'field_reference',''),
         '; reviewer_note=',coalesce(v.note,'')),true);
    INSERT INTO public.audit_logs
      (user_id,action_type,module,target_table,target_id,target_name,
       old_values,new_values,details,request_source,event_id,occurred_at)
    VALUES
      ('codex','AI_FIELD_FILL','building_data_ai_enrichment',v.target_table,
       target_id::text,v.building_name,
       jsonb_build_object(v.field_name,old_value),
       jsonb_build_object(v.field_name,v.proposed_value),
       jsonb_build_object('batch_ref',batch_ref,'candidate_ref',v.ref,'building_id',v.building_id,
        'field_name',v.field_name,'source_url',v.source->>'url','source_tier',v.source->>'tier',
        'ai_generated',true,'reversible',true,'evidence_group_id',batch_evidence_id),
       'codex_mcp',batch_ref||':'||v.ref,now());
    processed := processed + 1;
  END LOOP;
  IF processed<>100 THEN RAISE EXCEPTION 'Invalid committed count %',processed; END IF;
  IF (SELECT count(*) FROM public.building_data_field_provenance p
      WHERE p.evidence_group_id=batch_evidence_id)<>100 THEN
     RAISE EXCEPTION 'Provenance count mismatch';
  END IF;
  IF (SELECT count(*) FROM public.audit_logs a WHERE a.action_type='AI_FIELD_FILL'
       AND a.details->>'batch_ref'=batch_ref)<>100 THEN
     RAISE EXCEPTION 'Audit count mismatch';
  END IF;
END $ai_enrichment$;
